yakit.AutoInitYakit()

textString = cli.Text("textString",
    cli.setVerboseName("文本字符串"),
    cli.setRequired(true),
    cli.setHelp("先对文本字符串自动去重, 再进行排序。")
)

orderByType = cli.StringSlice("orderByType",
    cli.setVerboseName("排序依据"),
    cli.setRequired(true),
    cli.setDefault("ASCII"),
    cli.setSelectOption("ASCII", "ASCII"),
    cli.setSelectOption("字符长度", "strLength"),
)[0]

orderBy = cli.Bool("orderBy",
    cli.setVerboseName("升序"),
    cli.setRequired(true),
    cli.setHelp("默认升序")
)

cli.check()

// 按ASCII顺序排序字符串中的字符，支持升序和降序  
func SortStringByASCII(inputString, ascendingBool) {  
    if inputString == "" {  
        return ""  
    }  
      
    // 将字符串转换为字符数组  
    chars := str.ParseStringToLines(inputString)  
      
    // 使用Go标准库的sort.Slice按ASCII值排序  
    x.Sort(chars, func(i, j) {  
        if ascendingBool {  
            return chars[i] < chars[j]  // 升序  
        } else {  
            return chars[i] > chars[j]  // 降序  
        }  
    })  
      
    return str.Join(chars, "\n")
}


// 按字符串长度进行排序，支持升序和降序  
func SortStringByLength(inputString, ascending) {  
    if inputString == "" {  
        return ""  
    }  
      
    // 将字符串按行分割成数组  
    strings = str.Split(inputString, "\n")
      
    // 使用内置sort函数按长度排序  
    x.Sort(strings, func(i, j) {  
        len_i = len(strings[i])  
        len_j = len(strings[j])  
        if ascending {  
            return len_i < len_j  // 升序（短到长）  
        } else {  
            return len_i > len_j  // 降序（长到短）  
        }  
    })  
      
    return str.Join(strings, "\n")  
}  

func main(origin, orderByType, orderBy) {
    var result
    origin = str.Join(str.RemoveRepeat(str.ParseStringToLines(origin)), "\n")
    switch orderByType {
        case "ASCII":
            result = SortStringByASCII(origin, orderBy)
        case "strLength":
            result = SortStringByLength(origin, orderBy)
        default:
            log.Warn("未发现数据输入。")
    }

    // yakit.Text(result)
    yakit.EnableText("输出文本")
    yakit.TextTabData("输出文本", result)

}
main(textString, orderByType, orderBy)
